<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {api,can,useLoad,useCommand,session,selectMerchant,PageHeader,Feedback,EmptyState,StatusBadge,type DataRow} from '@tradeflow/ui'
import {useRows,text} from '../data'
import Pagination from '../components/Pagination.vue'
interface Merchant {merchantId:string;name:string;description:string;status:string;version:number}
interface Member {userId:string;status:string;role:string;version:number}
const platform=computed(()=>can('PLATFORM_USERS')),merchantAdmin=computed(()=>session.capabilities?.merchantRoles?.[session.merchantId||'']==='ADMIN')
const tab=ref(platform.value?'applications':'mine'),notice=ref(''),localError=ref(''),modal=ref(''),target=ref<DataRow>({}),reason=ref(''),approved=ref(true),newStatus=ref('ACTIVE')
const applications=useRows(()=>'/api/v1/admin/merchant-applications'),merchants=useRows(()=>'/api/v1/admin/merchants')
const own=useLoad<Merchant[]>(signal=>api('/merchants',{signal}))
const profile=useLoad<Merchant>(signal=>api('/merchants/'+encodeURIComponent(session.merchantId||''),{signal}))
const members=useLoad<Member[]>(signal=>api('/merchants/'+encodeURIComponent(session.merchantId||'')+'/members',{signal}))
const profileForm=ref({name:'',description:'',version:0}),memberForm=ref({userId:'',status:'ACTIVE',role:'OPERATOR',reason:''})
const command=useCommand('merchants')
let generation=0
onBeforeUnmount(()=>{generation++})
function open(kind:'review'|'state',row:DataRow){generation++;modal.value=kind;target.value={...row};reason.value='';approved.value=true;newStatus.value=String(row.status)==='ACTIVE'?'DISABLED':'ACTIVE';localError.value=''}
function close(){generation++;modal.value='';reason.value='';target.value={}}
/** 审核及经营启停携带展示时版本，冲突后刷新；迟到响应不能关闭新的操作表单。 */
async function submit(){localError.value='';if(!reason.value.trim()){localError.value='请填写操作原因';return}const g=generation,kind=modal.value,row={...target.value},body=kind==='review'?{approved:approved.value,reason:reason.value.trim(),version:Number(row.version)}:{status:newStatus.value,reason:reason.value.trim(),version:Number(row.version)},path=kind==='review'?`/admin/merchant-applications/${row.id}/review`:`/admin/merchants/${row.merchantId}/status`
 const result=await command.run(path,body,key=>api(path,{method:kind==='review'?'POST':'PATCH',body,key}));if(g!==generation||result===undefined)return;await command.reset();if(g!==generation)return;modal.value='';notice.value=kind==='review'?'审核结果已保存，申请人将收到站内通知。':'商家经营状态已更新，历史成员及处置身份保留。';await applications.reload();if(g===generation)await merchants.reload()
}
function select(id:string){selectMerchant(id)}
async function loadMine(){if(!session.merchantId){profile.clear();members.clear();return}await profile.reload();if(merchantAdmin.value)await members.reload()}
/** 当前商家资料独立版本；停用商家允许查看历史，新的资料写入由服务端拒绝。 */
async function saveProfile(){localError.value='';const g=generation,id=session.merchantId,body={...profileForm.value};if(!id)return
 const result=await command.run('profile:'+id,body,key=>api('/merchants/'+id,{method:'PATCH',body,key}));if(g!==generation||result===undefined)return;await command.reset();if(g===generation){notice.value='商家资料已保存。';await profile.reload();await own.reload()}}
async function saveMember(){localError.value='';if(!/^[1-9][0-9]{0,18}$/.test(memberForm.value.userId)||!memberForm.value.reason.trim()){localError.value='请填写有效目标用户编号和成员变更原因';return}const g=generation,id=session.merchantId;if(!id)return;const body={...memberForm.value,reason:memberForm.value.reason.trim(),merchantId:id}
 const result=await command.run('member:'+id+':'+body.userId,body,key=>api('/merchants/'+id+'/members',{method:'PUT',body,key}));if(g!==generation||result===undefined)return;await command.reset();if(g===generation){memberForm.value={userId:'',status:'ACTIVE',role:'OPERATOR',reason:''};notice.value='成员关系已更新，目标账号需重新登录。本商家职级已经更新。';await members.reload()}}
function editMember(row:Member){generation++;memberForm.value={userId:row.userId,status:row.status,role:row.role,reason:''};localError.value=''}
function reload(){if(!session.user)return;if(tab.value==='applications'&&platform.value)void applications.reload();if(tab.value==='all'&&platform.value)void merchants.reload();if(tab.value==='mine'){void own.reload();void loadMine()}}
watch(profile.data,value=>{if(value)profileForm.value={name:value.name,description:value.description,version:value.version}})
watch(tab,()=>{generation++;close();notice.value='';localError.value='';reload()})
watch(()=>session.merchantId,()=>{generation++;profile.clear();members.clear();profileForm.value={name:'',description:'',version:0};memberForm.value={userId:'',status:'ACTIVE',role:'OPERATOR',reason:''};close();notice.value='';if(tab.value==='mine')void loadMine()})
watch(()=>session.epoch,()=>{generation++;close();applications.clear();merchants.clear();own.clear();profile.clear();members.clear();memberForm.value={userId:'',status:'ACTIVE',role:'OPERATOR',reason:''};notice.value='';localError.value=''})
onMounted(reload)
</script>

<template><PageHeader title="商家与入驻" description="审核经营主体、管理经营状态，维护当前所属商家的资料和成员。"/><p v-if="notice" class="notice success-note" role="status">{{notice}}</p><Feedback :error="localError||command.error.value"/>
<section class="panel"><ElTabs v-model="tab"><ElTabPane v-if="platform" label="入驻申请" name="applications"/><ElTabPane v-if="platform" label="平台商家" name="all"/><ElTabPane label="我的商家" name="mine"/></ElTabs>
<template v-if="tab==='applications'&&platform"><div class="toolbar"><h2>入驻审核</h2><ElButton :loading="applications.loading.value" @click="applications.reload">刷新申请</ElButton></div><Feedback :loading="applications.loading.value" :error="applications.error.value"/><EmptyState v-if="!applications.loading.value&&!applications.items.value.length" title="当前页暂无申请"/><ElTable v-if="!applications.loading.value" :data="applications.items.value" row-key="id"><ElTableColumn prop="id" label="申请编号" min-width="110"/><ElTableColumn prop="userId" label="申请用户" min-width="110"/><ElTableColumn prop="merchantId" label="商家编号" min-width="180"/><ElTableColumn prop="name" label="商家名称" min-width="160"/><ElTableColumn prop="description" label="经营资料" min-width="240"/><ElTableColumn label="状态" width="130"><template #default="{row}"><StatusBadge :status="text(row.status)"/></template></ElTableColumn><ElTableColumn prop="reason" label="审核原因" min-width="160"/><ElTableColumn label="操作" width="110"><template #default="{row}"><ElButton v-if="row.status==='PENDING'" :disabled="command.busy.value" @click="open('review',row)">审核</ElButton><span v-else class="muted">已审核</span></template></ElTableColumn></ElTable><Pagination :page="applications.page.value" :count="applications.items.value.length" :total="applications.total.value" :has-next="applications.hasNext.value" :loading="applications.loading.value" @change="applications.change"/></template>
<template v-if="tab==='all'&&platform"><div class="toolbar"><h2>经营状态</h2><ElButton :loading="merchants.loading.value" @click="merchants.reload">刷新商家</ElButton></div><p class="notice">停用阻止新的经营操作；历史订单、退款义务和成员记录继续保留。</p><Feedback :loading="merchants.loading.value" :error="merchants.error.value"/><EmptyState v-if="!merchants.loading.value&&!merchants.items.value.length" title="当前页暂无商家"/><ElTable v-if="!merchants.loading.value" :data="merchants.items.value" row-key="merchantId"><ElTableColumn prop="merchantId" label="商家编号" min-width="190"/><ElTableColumn prop="name" label="商家名称" min-width="170"/><ElTableColumn prop="description" label="经营资料" min-width="240"/><ElTableColumn label="状态" width="120"><template #default="{row}"><StatusBadge :status="text(row.status)"/></template></ElTableColumn><ElTableColumn prop="version" label="版本" width="90"/><ElTableColumn label="操作" width="150"><template #default="{row}"><ElButton :disabled="command.busy.value" @click="open('state',row)">{{row.status==='ACTIVE'?'停用商家':'启用商家'}}</ElButton></template></ElTableColumn></ElTable><Pagination :page="merchants.page.value" :count="merchants.items.value.length" :total="merchants.total.value" :has-next="merchants.hasNext.value" :loading="merchants.loading.value" @change="merchants.change"/></template>
<template v-if="tab==='mine'"><div class="toolbar"><h2>所属商家</h2><ElButton :loading="own.loading.value" @click="own.reload();loadMine()">刷新资料</ElButton></div><Feedback :loading="own.loading.value" :error="own.error.value"/><EmptyState v-if="own.data.value&&!own.data.value.length" title="尚无有效商家成员身份" description="平台角色不能代替商家归属。请先申请入驻，或由平台维护成员与商家角色。"/><div v-for="row in own.data.value" :key="row.merchantId" class="merchant-choice"><div><strong>{{row.name}}</strong><p class="muted">{{row.merchantId}} · {{row.status==='ACTIVE'?'经营中':'已停用，保留历史处置'}}</p></div><ElButton :type="session.merchantId===row.merchantId?'primary':'default'" :disabled="session.merchantId===row.merchantId||command.busy.value" @click="select(row.merchantId)">{{session.merchantId===row.merchantId?'当前商家':'切换至此商家'}}</ElButton></div><Feedback :loading="profile.loading.value" :error="profile.error.value"/>
<template v-if="profile.data.value"><p class="notice">当前商家 {{profile.data.value.merchantId}}，资料版本 {{profile.data.value.version}}。权限按本商家的有效成员职级独立校验。</p><ElForm v-if="merchantAdmin" label-position="top" @submit.prevent="saveProfile"><h3>经营资料</h3><ElFormItem label="商家名称" required><ElInput v-model="profileForm.name" maxlength="120"/></ElFormItem><ElFormItem label="经营资料" required><ElInput v-model="profileForm.description" type="textarea" maxlength="500" :rows="3"/></ElFormItem><ElButton native-type="submit" type="primary" :loading="command.busy.value" :disabled="profile.data.value.status!=='ACTIVE'||!profileForm.name.trim()||!profileForm.description.trim()">保存资料</ElButton><p v-if="profile.data.value.status!=='ACTIVE'" class="field-hint">商家已停用，资料只读；历史处置身份仍保留。</p></ElForm><template v-else><h3>{{profile.data.value.name}}</h3><p>{{profile.data.value.description}}</p></template>
<template v-if="merchantAdmin"><div class="toolbar"><h3>历史与当前成员</h3><ElButton :loading="members.loading.value" @click="members.reload">刷新成员</ElButton></div><Feedback :loading="members.loading.value" :error="members.error.value"/><ElTable :data="members.data.value||[]" row-key="userId"><ElTableColumn prop="userId" label="用户编号"/><ElTableColumn label="成员状态"><template #default="{row}"><StatusBadge :status="row.status"/></template></ElTableColumn><ElTableColumn prop="role" label="本商家职级"/><ElTableColumn prop="version" label="版本"/><ElTableColumn label="操作"><template #default="{row}"><ElButton :disabled="command.busy.value" @click="editMember(row)">维护成员</ElButton></template></ElTableColumn></ElTable><ElForm label-position="top" @submit.prevent="saveMember"><h3>新增或启停成员</h3><p class="field-hint">此处维护本商家的职级和成员状态，不能移除最后一个有效管理员；目标账号授权变更后需重新登录。</p><ElFormItem label="目标用户编号" required><ElInput v-model.trim="memberForm.userId" inputmode="numeric" maxlength="19"/></ElFormItem><ElFormItem label="本商家职级" required><ElSelect v-model="memberForm.role"><ElOption label="管理员" value="ADMIN"/><ElOption label="操作员" value="OPERATOR"/></ElSelect></ElFormItem><ElFormItem label="成员状态" required><ElSelect v-model="memberForm.status"><ElOption label="有效成员" value="ACTIVE"/><ElOption label="停用成员（保留记录）" value="DISABLED"/></ElSelect></ElFormItem><ElFormItem label="变更原因" required><ElInput v-model="memberForm.reason" type="textarea" maxlength="500"/></ElFormItem><ElButton native-type="submit" type="primary" :loading="command.busy.value">保存成员关系</ElButton></ElForm></template></template></template>
</section>
<ElDialog :model-value="!!modal" :title="modal==='review'?'审核入驻申请':'变更商家经营状态'" width="600px" @close="close"><ElForm label-position="top" @submit.prevent="submit"><p class="notice">{{text(target.name)}} · {{text(target.merchantId)}} · 基于版本 {{text(target.version)}} 提交。版本冲突时请关闭并刷新核对。</p><ElFormItem v-if="modal==='review'" label="审核结论" required><ElSelect v-model="approved"><ElOption label="通过申请" :value="true"/><ElOption label="拒绝申请" :value="false"/></ElSelect></ElFormItem><ElFormItem v-else label="经营状态" required><ElSelect v-model="newStatus"><ElOption label="启用经营" value="ACTIVE"/><ElOption label="停用经营，保留历史处置" value="DISABLED"/></ElSelect></ElFormItem><ElFormItem label="操作原因" required><ElInput v-model="reason" type="textarea" maxlength="500" :rows="3"/></ElFormItem><Feedback :error="localError||command.error.value"/><ElButton native-type="submit" type="primary" :loading="command.busy.value">确认提交</ElButton><ElButton @click="close">关闭</ElButton></ElForm></ElDialog>
</template>
<style scoped>.merchant-choice{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:16px 0;border-bottom:1px solid var(--el-border-color-lighter)}.merchant-choice p{overflow-wrap:anywhere}.el-form{max-width:760px;margin:24px 0}@media(max-width:600px){.merchant-choice{align-items:flex-start;flex-direction:column}}</style>
